import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement from specification
  group.position.set(0, 1.85, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Create plane geometry for the background image
  // 512x320 source → 1.6:1 aspect ratio
  const planeGeometry = new THREE.PlaneGeometry(3.2, 2.0);

  // Load the texture
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material for static textured plane
  const material = new THREE.MeshBasicMaterial({
    map: texture,
  });

  // Create and add the plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, material);
  group.add(planeMesh);

  // Render text content overlay via font atlas
  const textContent = config.textContent || 'Atelier Noir — precise · luxury · technical';

  const textMesh = ctx.fontAtlas.createText(textContent, {
    size: 0.25,
    weight: 400,
    fontFamily: 'Lora',
    color: config.colors?.ink || 0x16161d,
    align: 'center',
    anchorX: 'center',
    anchorY: 'middle',
  });

  if (textMesh) {
    textMesh.position.z = 0.2;
    group.add(textMesh);
  }

  // Initialize event handlers (empty for static composition)
  group.userData.handlers = {};

  // Cleanup function for resource disposal
  group.userData.cleanup = function() {
    planeGeometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
